    @classmethod
    def Switch( cls, switch: Boolean = None, false: Boolean = None, true: Boolean = None):
        """Node Switch.
        
        Jump: False
        
        **Fixed inputs**
        - Node parameter 'input_type' = 'BOOLEAN'
        
        Parameters
        ----------
        switch : Boolean, optional
            Socket 'Switch' (default: None)
        false : Boolean, optional
            Socket 'False' (default: None)
        true : Boolean, optional
            Socket 'True' (default: None)
        

        Returns
        -------
        Self
            Default output socket wrapped in the calling class.
        """
        node = Node(
            'Switch',
            named_sockets={'ID_Switch': switch, 'ID_False': false, 'ID_True': true},
            input_type='BOOLEAN')
        
        return cls(node._out)
